describe('Notification Message Tests', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    });

    it('should display a success notification when the link is clicked', () => {
        cy.get('a[href="/notification_message_rendered"]').click();
        cy.get('#flash').should('be.visible');
        cy.get('#flash').should('contain.text', 'Action successful');
    });

    it('should display an error notification when the link is clicked', () => {
        cy.get('a[href="/notification_message_rendered"]').click();
        cy.get('#flash').should('be.visible');
        cy.get('#flash').should('contain.text', 'Action unsuccessful');
    });

    it('should dismiss the notification when the close icon is clicked', () => {
        cy.get('a[href="/notification_message_rendered"]').click();
        cy.get('#flash').should('be.visible');
        cy.get('.close').click();
        cy.get('#flash').should('not.be.visible');
    });
});
